// Clean-room TSVC s232 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s232_triangular_row_square_recurrence(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<9||length>51{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];if !(2..=5).contains(&nr){return -1;}let n=nr as usize;let nn=n*n;if length!=1+2*nn{return -1;}let mut a=[0i64;25];let mut b=[0i64;25];for i in 0..nn{let x=v[1+i];let y=v[1+nn+i];if !(-1..=1).contains(&x)||!(-1..=1).contains(&y){return -1;}a[i]=x;b[i]=y;}if output.is_null()||capacity<8*nn{return -2;}for j in 1..n{for i in 1..=j{let x=a[j*n+i-1];a[j*n+i]=x*x+b[j*n+i];}}for i in 0..nn{let bits=a[i]as u64;for j in 0..8{output.add(8*i+j).write((bits>>(8*j))as u8);}}nn as i64}
